(function(){const encoded="";window.MBrainImportedSlots=(async()=>{try{if(typeof DecompressionStream==="undefined")throw new Error("DecompressionStream unavailable");const binary=atob(encoded);const bytes=Uint8Array.from(binary,c=>c.charCodeAt(0));const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));const text=await new Response(stream).text();const d=JSON.parse(text);return d.rows.map(([name,b,p,rtp,vol,t,date])=>({name,book:d.books[b],provider:d.providers[p]==="None"?"":d.providers[p],rtp,vol,sourceType:d.types[t],date}));}catch(e){console.warn("Import catalogo slot non disponibile",e);return []}})()})();